import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const root = fileURLToPath(new URL("../", import.meta.url));
const result = await build({
  entryPoints: [
    fileURLToPath(new URL("../server/reading/docx.mjs", import.meta.url)),
  ],
  bundle: true,
  platform: "node",
  format: "cjs",
  write: false,
  legalComments: "inline",
  minify: true,
});
const output = new URL("../server/reading/docx-reader.cjs", import.meta.url);
const generated =
  "// Generated by scripts/build-reading-parser.mjs; sax 1.6.1, BlueOak-1.0.0. See docx-reader.LICENSE.\n" +
  result.outputFiles[0].text;
if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== generated)
    throw Error("STALE_READING_PARSER");
  if (
    (await readFile(
      new URL("../server/reading/docx-reader.LICENSE", import.meta.url),
      "utf8",
    )) !==
    (await readFile(
      new URL("../node_modules/sax/LICENSE.md", import.meta.url),
      "utf8",
    ))
  )
    throw Error("STALE_READING_LICENSE");
} else {
  await writeFile(output, generated);
  await writeFile(
    new URL("../server/reading/docx-reader.LICENSE", import.meta.url),
    await readFile(new URL("../node_modules/sax/LICENSE.md", import.meta.url)),
  );
}
console.log("Reading XML parser bundle verified/generated");
